// @FIGURE_CODE_BEGIN
/* ---------------- element spec (one line per drawn element) ----------------
   input circle       → CircleGeometry(0.45) white fill + RingGeometry outline #1a1a1a
                        (CAMERA-FACING billboard group → renders as a TRUE circle)
   active input cell  → same billboard, fill #b6bcbc, black italic serif label
   zero-pad glyph     → addLabel('0') italic serif at the padded lattice site
   kernel cell        → PlaneGeometry(KS) white fill + LineLoop border #111  (lies in
                        the tilted sheet → projects as the source's parallelogram)
   hidden circle      → CircleGeometry(0.45) + RingGeometry outline #d0d4d4 (billboard)
   active output      → fill #b6bcbc, ring #111, teal #1f6f63 label
   connectors (x9)    → THREE.Line, 2 verts, terracotta #d98878
   kernel→⊕→h link    → THREE.Line, LineDashedMaterial, terracotta
   ⊗ , ⊕              → LineLoop(r=0.45) + 2 Lines, terracotta #c8654e, billboard
   all text           → addLabel (italic serif indices 12px, roman serif captions 15px)
   Lattice sites live in three parallel world sheets (normal = world X); the
   axonometric camera does ALL the shearing — no geometry is pre-sheared.
---------------------------------------------------------------------------*/

const K        = 1.224745;          // sheet-local unit → 1 screen unit under the iso camera
const COL_STEP = 1.00 * K;          // column j : screen right-up 30°, 1.00 screen unit
const ROW_STEP = 1.15 * K;          // row i    : screen straight down, 1.15 screen units
const CR       = 0.45;              // circle radius (billboard → screen units)
const KS       = 1.05 * K;          // kernel square side (1.05 screen units per edge)

const TERRA = 0xd98878, SYMC = 0xc8654e;
const FILL_ACT = 0xb6bcbc, WHITE = 0xffffff, VISIT = 0xdde9e4;
const SERIF = "font-family:Georgia,'Times New Roman',serif;";
const it = (h) => `<span style="${SERIF}font-style:italic">${h}</span>`;
const rm = (h) => `<span style="${SERIF}">${h}</span>`;

/* screen(sx,sy) → world point that projects exactly there under the iso camera */
function s2w(sx, sy) {
  return new THREE.Vector3(1.414214 * sx, 1.224745 * sy + 0.707107 * sx, 0);
}
function makeSheet(sx, sy) {
  const g = new THREE.Group();
  g.rotation.y = Math.PI / 2;               // local +X → world −Z, local +Y → world +Y
  g.position.copy(s2w(sx, sy));
  scene.add(g);
  g.updateMatrixWorld(true);
  return g;
}
const gIn = makeSheet(-8.0, 1.6);
const gW  = makeSheet(-0.5, -0.6);
const gH  = makeSheet(5.4, 0.9);

function cellLocal(i, j) { return new THREE.Vector3((j - 1) * COL_STEP, -(i - 1) * ROW_STEP, 0); }

/* ---------------- camera-facing billboards (keeps circles circular) -------- */
const billboards = [];
function makeBillboard(worldPos) {
  const g = new THREE.Group();
  g.position.copy(worldPos);
  scene.add(g);
  billboards.push(g);
  return g;
}
function syncBillboards() { for (const g of billboards) g.quaternion.copy(camera.quaternion); }

/* shared circle geometry */
const discGeo   = new THREE.CircleGeometry(CR, 56);
const ringGeoIn = new THREE.RingGeometry(CR - 0.040, CR, 64);
const ringGeoH  = new THREE.RingGeometry(CR - 0.032, CR, 64);

function addCircle(sheet, i, j, ringGeo, strokeHex) {
  const world = sheet.localToWorld(cellLocal(i, j));
  const g = makeBillboard(world);
  const fillMat = new THREE.MeshBasicMaterial({ color: WHITE, depthTest: false });
  const fill = new THREE.Mesh(discGeo, fillMat);
  fill.renderOrder = 2;
  const ringMat = new THREE.MeshBasicMaterial({ color: strokeHex, depthTest: false });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.position.z = 0.002; ring.renderOrder = 3;
  g.add(fill); g.add(ring);
  return { group: g, fill, ring, fillMat, ringMat, world };
}

/* ---------------- input grid X : 4 × 6 ---------------- */
const inCells = [];
for (let i = 1; i <= 4; i++) {
  inCells[i] = [];
  for (let j = 1; j <= 6; j++) {
    const c = addCircle(gIn, i, j, ringGeoIn, 0x1a1a1a);
    c.lbl = addLabel(it(`x<sub>${i}${j}</sub>`), c.world, { fontSize: '12px', color: '#2b3030' });
    registerInteractive(c.fill, {
      title: 'Input X — receptive field',
      tooltip: 'Drag to move the 3×3 window',
      body: 'The shaded 3×3 block is the receptive field of the hidden unit currently being computed. Drag it across X: the highlighted output cell follows, one scalar per spatial position.'
    });
    inCells[i][j] = c;
  }
}

/* ---------------- weight grid Ω : 3 × 3 squares ---------------- */
const kCells = [];
const sqGeo = new THREE.PlaneGeometry(KS, KS);
const hq = KS / 2;
const borderGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-hq, -hq, 0), new THREE.Vector3(hq, -hq, 0),
  new THREE.Vector3(hq, hq, 0), new THREE.Vector3(-hq, hq, 0)
]);
for (let k = 1; k <= 3; k++) {
  kCells[k - 1] = [];
  for (let l = 1; l <= 3; l++) {
    const cx = (l - 1) * KS, cy = -(k - 1) * KS;
    const fill = new THREE.Mesh(sqGeo, new THREE.MeshBasicMaterial({ color: WHITE, depthTest: false }));
    fill.position.set(cx, cy, 0); fill.renderOrder = 2;
    const bord = new THREE.LineLoop(borderGeo, new THREE.LineBasicMaterial({ color: 0x111111, depthTest: false }));
    bord.position.set(cx, cy, 0.004); bord.renderOrder = 3;
    gW.add(fill); gW.add(bord);
    const world = gW.localToWorld(new THREE.Vector3(cx, cy, 0));
    addLabel(it(`&omega;<sub>${k}${l}</sub>`), world, { fontSize: '12px', color: '#111' });
    registerInteractive(fill, {
      title: `Weight ω${k}${l}`,
      tooltip: 'Kernel weight — shared at every position',
