const symAdd = symbol('+', 2.6, 1.2);
const plusWorld = symAdd.position.clone();
registerInteractive(symMul, { title: 'Element-wise multiply ⊗', tooltip: 'Element-wise multiplication', body: 'Each shaded input value is multiplied by the weight of the kernel cell it is wired to — nine independent products.' });
registerInteractive(symAdd, { title: 'Summation ⊕', tooltip: 'Sum of the nine products', body: 'The nine products are added together (plus a bias, omitted here) to give the single hidden unit on the right.' });

/* ---------------- static text ---------------- */
