// @FIGURE_CODE_BEGIN
/* ---------------- element spec (one line per drawn element) ----------------
   input circle       → CircleGeometry(0.45) white fill + RingGeometry outline #1a1a1a
                        (CAMERA-FACING billboard group → renders as a TRUE circle)
   active input cell  → same billboard, fill #b6bcbc, black italic serif label
   zero-pad glyph     → addLabel('0') italic serif at the padded lattice site
   kernel cell        → PlaneGeometry(KS) white fill + LineLoop border #111  (lies in
                        the tilted sheet → projects as the source's parallelogram)
   hidden circle      → CircleGeometry(0.45) + RingGeometry outline #d0d4d4 (billboard)
   active output      → fill #b6bcbc, ring #111, teal #1f6f63 label
   connectors (x9)    → THREE.Line, 2 verts, terracotta #d98878
   kernel→⊕→h link    → THREE.Line, LineDashedMaterial, terracotta
   ⊗ , ⊕              → LineLoop(r=0.45) + 2 Lines, terracotta #c8654e, billboard
   all text           → addLabel (italic serif indices 14px, roman serif captions 17px)
   Lattice sites live in three parallel world sheets (normal = world X); the
   axonometric camera does ALL the shearing — no geometry is pre-sheared.
---------------------------------------------------------------------------*/

const K        = 1.224745;          // sheet-local unit → 1 screen unit under the iso camera
const COL_S    = 1.05;              // column j : screen right-up 30°, 1.05 screen units
const ROW_S    = 1.22;              // row i    : screen straight down, 1.22 screen units
const KS_S     = 1.20;              // kernel square edge, screen units (enlarged Ω sheet)
const COL_STEP = COL_S * K, ROW_STEP = ROW_S * K, KS = KS_S * K;
const CR       = 0.45;              // circle radius (billboard → screen units)

const TERRA = 0xd98878, SYMC = 0xc8654e;
const FILL_ACT = 0xb6bcbc, WHITE = 0xffffff, VISIT = 0xdde9e4;
const SERIF = "font-family:Georgia,'Times New Roman',serif;";
const it = (h) => `<span style="${SERIF}font-style:italic">${h}</span>`;
const rm = (h) => `<span style="${SERIF}">${h}</span>`;

/* screen(sx,sy) → world point that projects exactly there under the iso camera */
function s2w(sx, sy) {
  return new THREE.Vector3(1.414214 * sx, 1.224745 * sy + 0.707107 * sx, 0);
}
function makeSheet(sx, sy) {
  const g = new THREE.Group();
  g.rotation.y = Math.PI / 2;               // local +X → world −Z, local +Y → world +Y
  g.position.copy(s2w(sx, sy));
  scene.add(g);
  g.updateMatrixWorld(true);
  return g;
}

/* layout in SCREEN units, matched to the source panel (a) composition */
const IN0 = [-8.00,  2.90];   // x11
const W0  = [-1.92,  0.89];   // ω11 centre
const H0  = [ 3.42, -1.78];   // h11
const MULP = [-1.23, 3.04];   // ⊗  between shaded patch and top of weight sheet
const ADDP = [ 2.22, -0.31];  // ⊕  between weight sheet and hidden layer

const gIn = makeSheet(IN0[0], IN0[1]);
const gW  = makeSheet(W0[0],  W0[1]);
const gH  = makeSheet(H0[0],  H0[1]);

function cellLocal(i, j) { return new THREE.Vector3((j - 1) * COL_STEP, -(i - 1) * ROW_STEP, 0); }

/* ---------------- camera-facing billboards (keeps circles circular) -------- */
const billboards = [];
function makeBillboard(worldPos) {
  const g = new THREE.Group();
  g.position.copy(worldPos);
  scene.add(g);
  billboards.push(g);
  return g;
}
function syncBillboards() { for (const g of billboards) g.quaternion.copy(camera.quaternion); }

const discGeo   = new THREE.CircleGeometry(CR, 56);
const ringGeoIn = new THREE.RingGeometry(CR - 0.042, CR, 64);
const ringGeoH  = new THREE.RingGeometry(CR - 0.032, CR, 64);

function addCircle(sheet, i, j, ringGeo, strokeHex) {
  const world = sheet.localToWorld(cellLocal(i, j));
  const g = makeBillboard(world);
  const fillMat = new THREE.MeshBasicMaterial({ color: WHITE, depthTest: false });
  const fill = new THREE.Mesh(discGeo, fillMat);
  fill.renderOrder = 2;
  const ringMat = new THREE.MeshBasicMaterial({ color: strokeHex, depthTest: false });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.position.z = 0.002; ring.renderOrder = 3;
  g.add(fill); g.add(ring);
  return { group: g, fill, ring, fillMat, ringMat, world };
}

/* ---------------- input grid X : 4 × 6 ---------------- */
const inCells = [];
for (let i = 1; i <= 4; i++) {
  inCells[i] = [];
  for (let j = 1; j <= 6; j++) {
    const c = addCircle(gIn, i, j, ringGeoIn, 0x1a1a1a);
    c.lbl = addLabel(it(`x<sub>${i}${j}</sub>`), c.world, { fontSize: '14px', color: '#2b3030' });
    registerInteractive(c.fill, {
      title: 'Input X — receptive field',
      tooltip: 'Drag to move the 3×3 window',
      body: 'The shaded 3×3 block is the receptive field of the hidden unit currently being computed. Drag it across X: the highlighted output cell follows, one scalar per spatial position.'
    });
    inCells[i][j] = c;
  }
}

/* ---------------- weight grid Ω : 3 × 3 squares ---------------- */
const kCells = [];
const sqGeo = new THREE.PlaneGeometry(KS, KS);
const hq = KS / 2;
const borderGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-hq, -hq, 0), new THREE.Vector3(hq, -hq, 0),
  new THREE.Vector3(hq, hq, 0), new THREE.Vector3(-hq, hq, 0)
]);
for (let k = 1; k <= 3; k++) {
  kCells[k - 1] = [];
  for (let l = 1; l <= 3; l++) {
    const cx = (l - 1) * KS, cy = -(k - 1) * KS;
    const fill = new THREE.Mesh(sqGeo, new THREE.MeshBasicMaterial({ color: WHITE, depthTest: false }));
    fill.position.set(cx, cy, 0); fill.renderOrder = 2;
    const bord = new THREE.LineLoop(borderGeo, new THREE.LineBasicMaterial({ color: 0x111111, depthTest: false }));
    bord.position.set(cx, cy, 0.004); bord.renderOrder = 3;
    gW.add(fill); gW.add(bord);
    const world = gW.localToWorld(new THREE.Vector3(cx, cy, 0));   // centre of the square
    addLabel(it(`&omega;<sub>${k}${l}</sub>`), world, { fontSize: '14px', color: '#111' });
    registerInteractive(fill, {
      title: `Weight ω${k}${l}`,
      tooltip: 'Kernel weight — shared at every position',
      body: 'These nine weights are the entire parameter set of the layer. They are reused unchanged at every spatial position (weight sharing), which is what distinguishes a convolution from a fully connected layer.'
    });
    kCells[k - 1][l - 1] = { world };
  }
}

/* ---------------- hidden layer H1 : up to 4 × 6 ---------------- */
const outCells = [];
for (let i = 1; i <= 4; i++) {
  outCells[i] = [];
  for (let j = 1; j <= 6; j++) {
    const c = addCircle(gH, i, j, ringGeoH, 0xd0d4d4);
    c.lbl = addLabel(it(`h<sub>${i}${j}</sub>`), c.world, { fontSize: '14px', color: '#a9b0b0' });
    c.oi = i; c.oj = j;
    registerInteractive(c.fill, {
      title: `Output h${i}${j}`,
      tooltip: `Click: compute h${i}${j}`,
      body: 'Each hidden unit is one scalar: the dot product of the 3×3 kernel Ω with the 3×3 input patch centred on the matching input position (zeros supplied where the patch hangs off the edge).'
    });
    outCells[i][j] = c;
  }
}

/* ---------------- connectors, dashed link ---------------- */
const connectors = [];
for (let n = 0; n < 9; n++) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const ln = new THREE.Line(g, new THREE.LineBasicMaterial({ color: TERRA, transparent: true, opacity: 0.95, depthTest: false }));
  ln.renderOrder = 6;
  scene.add(ln); connectors.push(ln);
}
const dashGeo = new THREE.BufferGeometry();
dashGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
const dashLine = new THREE.Line(dashGeo, new THREE.LineDashedMaterial({
  color: TERRA, dashSize: 0.30, gapSize: 0.22, transparent: true, depthTest: false
}));
dashLine.renderOrder = 6;
scene.add(dashLine);

/* ---------------- ⊗ and ⊕ symbols (camera-facing) ---------------- */
function symbol(kind, sx, sy) {
  const g = makeBillboard(s2w(sx, sy));
  const r = 0.45, mat = new THREE.LineBasicMaterial({ color: SYMC, depthTest: false });
  const pts = [];
  for (let k = 0; k < 64; k++) { const a = k / 64 * Math.PI * 2; pts.push(new THREE.Vector3(Math.cos(a) * r, Math.sin(a) * r, 0)); }
  const loop = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), mat);
  loop.renderOrder = 7; g.add(loop);
  const dd = r * 0.60;
  const segs = kind === 'x' ? [[-dd, -dd, dd, dd], [-dd, dd, dd, -dd]] : [[-dd, 0, dd, 0], [0, -dd, 0, dd]];
  segs.forEach(s => {
    const ln = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(s[0], s[1], 0), new THREE.Vector3(s[2], s[3], 0)]), mat);
    ln.renderOrder = 7; g.add(ln);
  });
  g.updateMatrixWorld(true);
  return g;
}
const symMul = symbol('x', MULP[0], MULP[1]);
const symAdd = symbol('+', ADDP[0], ADDP[1]);
const plusWorld = symAdd.position.clone();
registerInteractive(symMul, { title: 'Element-wise multiply ⊗', tooltip: 'Element-wise multiplication', body: 'Each shaded input value is multiplied by the weight of the kernel cell it is wired to — nine independent products.' });
registerInteractive(symAdd, { title: 'Summation ⊕', tooltip: 'Sum of the nine products', body: 'The nine products are added together (plus a bias, omitted here) to give the single hidden unit on the right.' });

/* ---------------- static text ---------------- */
addLabel(rm('Input, <b>X</b>'), s2w(-7.4, -2.30), { fontSize: '17px', color: '#000' });
addLabel(rm('Weights, <b>&Omega;</b>'), s2w(-1.30, -3.70), { fontSize: '17px', color: '#000' });
addLabel(rm('Hidden layer, <b>H</b><sub>1</sub>'), s2w(5.70, -6.70), { fontSize: '17px', color: '#000' });
const panelLbl = addLabel(rm('a)'), s2w(-9.50, 5.60), { fontSize: '22px', color: '#000' });

/* zero-padding glyph pool */
const zeroLabels = [];
for (let n = 0; n < 9; n++) {
  const e = addLabel(it('0'), new THREE.Vector3(0, 0, 0), { fontSize: '15px', color: '#111' });
  e.div.style.visibility = 'hidden';
  zeroLabels.push(e);
}

/* ---------------- illustrative numeric values for the readout ---------------- */
const WV = [[0.5, -0.2, 0.3], [-0.1, 0.8, 0.1], [0.2, -0.4, 0.6]];
function xval(i, j) { if (i < 1 || i > 4 || j < 1 || j > 6) return 0; return ((i * 4 + j * 5) % 9) + 1; }

/* ---------------- state + update ---------------- */
const PANELS = { a: { row: 2, col: 3 }, b: { row: 3, col: 5 }, c: { row: 3, col: 1 }, d: { row: 1, col: 6 } };
const state = { row: 2, col: 3, stride: 1 };
const visited = new Set();
const readoutEl = document.getElementById('readout');
const outSizeEl = document.getElementById('outSize');

function snapIdx(v, s, max) {
  let k = Math.round((v - 1) / s);
  k = Math.max(0, Math.min(Math.floor((max - 1) / s), k));
  return 1 + k * s;
}

function update() {
  const s = state.stride, r0 = state.row, c0 = state.col;

  for (let i = 1; i <= 4; i++) for (let j = 1; j <= 6; j++) {
    const c = inCells[i][j];
    const act = Math.abs(i - r0) <= 1 && Math.abs(j - c0) <= 1;
    c.fillMat.color.setHex(act ? FILL_ACT : WHITE);
    c.lbl.div.style.color = act ? '#000' : '#2b3030';
    c.lbl.div.style.fontWeight = act ? '600' : '400';
  }

  let z = 0, n = 0;
  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
    const i = r0 + di, j = c0 + dj;
    const wp = gIn.localToWorld(cellLocal(i, j));
    if (i < 1 || i > 4 || j < 1 || j > 6) {
      const zl = zeroLabels[z++]; zl.pos.copy(wp); zl.div.style.visibility = 'visible';
    }
    const kc = kCells[di + 1][dj + 1];
    const ln = connectors[n++], arr = ln.geometry.attributes.position.array;
    arr[0] = wp.x; arr[1] = wp.y; arr[2] = wp.z;
    arr[3] = kc.world.x; arr[4] = kc.world.y; arr[5] = kc.world.z;
    ln.geometry.attributes.position.needsUpdate = true;
    ln.geometry.computeBoundingBox(); ln.geometry.computeBoundingSphere();
  }
  for (; z < zeroLabels.length; z++) zeroLabels[z].div.style.visibility = 'hidden';

  const nr = Math.ceil(4 / s), nc = Math.ceil(6 / s);
  const oi = (r0 - 1) / s + 1, oj = (c0 - 1) / s + 1;
  let active = null;
  for (let i = 1; i <= 4; i++) for (let j = 1; j <= 6; j++) {
    const c = outCells[i][j];
    const vis = i <= nr && j <= nc;
    c.group.visible = vis;
    c.lbl.div.style.visibility = vis ? 'visible' : 'hidden';
    const act = vis && i === oi && j === oj;
    if (act) active = c;
    c.fillMat.color.setHex(act ? FILL_ACT : (visited.has(i + '_' + j) ? VISIT : WHITE));
    c.ringMat.color.setHex(act ? 0x111111 : 0xd0d4d4);
    c.lbl.div.style.color = act ? '#1f6f63' : '#a9b0b0';
    c.lbl.div.style.fontWeight = act ? '700' : '400';
  }

  const start = gW.localToWorld(new THREE.Vector3(2.5 * KS, -1.5 * KS, 0));
  const end = active ? active.world : plusWorld;
  const da = dashGeo.attributes.position.array;
  da[0] = start.x; da[1] = start.y; da[2] = start.z;
  da[3] = plusWorld.x; da[4] = plusWorld.y; da[5] = plusWorld.z;
  da[6] = end.x; da[7] = end.y; da[8] = end.z;
  dashGeo.attributes.position.needsUpdate = true;
  dashGeo.computeBoundingBox(); dashGeo.computeBoundingSphere();
  dashLine.computeLineDistances();

  // panel caption — always visible, even away from the canonical a)–d) positions
  let letter = '';
  for (const key in PANELS) if (PANELS[key].row === r0 && PANELS[key].col === c0) letter = key;
  let cap;
  if (letter && s === 1) cap = `${letter})`;
  else if (letter) cap = `${letter})<span style="font-size:14px"> &middot; stride ${s}</span>`;
  else cap = `<span style="font-size:15px">&mdash; custom position (h<sub>${oi}${oj}</sub>${s > 1 ? ', stride ' + s : ''})</span>`;
  panelLbl.div.innerHTML = rm(cap);
  document.querySelectorAll('#panelBtns button').forEach(b =>
    b.classList.toggle('active', s === 1 && letter === b.dataset.panel));

  // readout (illustrative sample numbers)
  let rows = '', sum = 0;
  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
    const i = r0 + di, j = c0 + dj, k = di + 2, l = dj + 2;
    const xv = xval(i, j), wv = WV[k - 1][l - 1], pr = xv * wv;
    sum += pr;
    const pad = (i < 1 || i > 4 || j < 1 || j > 6);
    const nm = pad ? '<span style="color:#c8654e">0</span>' : `x<sub>${i}${j}</sub>`;
    rows += `<div>${nm}&middot;&omega;<sub>${k}${l}</sub> = ${xv} &times; ${wv.toFixed(2)} = ${pr.toFixed(2)}</div>`;
  }
  readoutEl.innerHTML = rows +
    `<div style="border-top:1px solid #bbb;margin-top:3px;padding-top:3px;color:#1f6f63">` +
    `h<sub>${oi}${oj}</sub> = &Sigma; = ${sum.toFixed(2)}</div>`;
  outSizeEl.innerHTML = `H<sub>1</sub> size = ${nr} &times; ${nc} &nbsp;(window centre: input row ${r0}, col ${c0})`;
}

update();

/* ---------------- camera + explicit fit (after geometry) ----------------
   The three sheets lie in three parallel planes, so the scene AABB projects
   far larger than the drawing actually is — the automatic fit would shrink the
   figure to ~40% of the frame. The screen-space extent is known exactly here
   (everything is authored in screen units through s2w), so the zoom is solved
   directly from it and re-solved on resize.                                  */
const FIT = { cx: -0.80, cy: -0.50, w: 19.6, h: 14.0, frac: 0.95 };
function fitZoom() {
  const a = (canvas.clientWidth || 4) / (canvas.clientHeight || 3);
  return Math.min(6 * FIT.frac / FIT.h, 6 * a * FIT.frac / FIT.w);
}
syncBillboards();
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  target: s2w(FIT.cx, FIT.cy).toArray(),
  zoom: fitZoom(),
  heightFraction: 0.95
});
syncBillboards();
function refit() {
  if (_userMovedCamera) return;
  const z = fitZoom();
  if (Math.abs(camera.zoom - z) > 1e-4) { camera.zoom = z; camera.updateProjectionMatrix(); controls.update(); }
}
new ResizeObserver(refit).observe(canvas);
document.getElementById('btnReset').style.display = '';
document.getElementById('btnReset').addEventListener('click', () => {
  camera.zoom = fitZoom(); camera.updateProjectionMatrix(); controls.update(); syncBillboards();
});
controls.addEventListener('change', syncBillboards);
(function billboardTick() { syncBillboards(); requestAnimationFrame(billboardTick); })();

/* ---------------- drag the window ---------------- */
const inputPlane = new THREE.Plane(new THREE.Vector3(1, 0, 0), -gIn.position.x);
const rcast = new THREE.Raycaster();
let dragging = false;

function planeCell(ev) {
  const rect = canvas.getBoundingClientRect();
  const ndc = new THREE.Vector2(
    ((ev.clientX - rect.left) / rect.width) * 2 - 1,
    -((ev.clientY - rect.top) / rect.height) * 2 + 1);
  rcast.setFromCamera(ndc, camera);
  const p = new THREE.Vector3();
  if (!rcast.ray.intersectPlane(inputPlane, p)) return null;
  const loc = gIn.worldToLocal(p.clone());
  return { i: -loc.y / ROW_STEP + 1, j: loc.x / COL_STEP + 1 };
}
function applyCell(c) {
  const s = state.stride;
  state.row = snapIdx(c.i, s, 4);
  state.col = snapIdx(c.j, s, 6);
  update();
}
canvas.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const c = planeCell(e);
  if (c && c.i > -0.6 && c.i < 5.6 && c.j > -0.9 && c.j < 7.6) {
    dragging = true;
    controls.enabled = false;
    stopSweep();
    applyCell(c);
  }
}, true);
window.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const c = planeCell(e);
  if (c) applyCell(c);
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

/* ---------------- click an output cell ---------------- */
canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const ndc = new THREE.Vector2(
    ((e.clientX - rect.left) / rect.width) * 2 - 1,
    -((e.clientY - rect.top) / rect.height) * 2 + 1);
  rcast.setFromCamera(ndc, camera);
  const meshes = [];
  for (let i = 1; i <= 4; i++) for (let j = 1; j <= 6; j++) if (outCells[i][j].group.visible) meshes.push(outCells[i][j].fill);
  const hit = rcast.intersectObjects(meshes, false)[0];
  if (!hit) return;
  for (let i = 1; i <= 4; i++) for (let j = 1; j <= 6; j++) {
    if (outCells[i][j].fill === hit.object) {
      stopSweep();
      state.row = (i - 1) * state.stride + 1;
      state.col = (j - 1) * state.stride + 1;
      update();
    }
  }
});

/* ---------------- UI ---------------- */
document.querySelectorAll('#panelBtns button').forEach(b => {
  b.addEventListener('click', () => {
    stopSweep(); visited.clear();
    state.stride = 1;
    document.getElementById('strideSlider').value = '1';
    document.getElementById('strideOut').textContent = '1';
    state.row = PANELS[b.dataset.panel].row;
    state.col = PANELS[b.dataset.panel].col;
    update();
  });
});

const strideSlider = document.getElementById('strideSlider');
strideSlider.addEventListener('input', () => {
  state.stride = parseInt(strideSlider.value, 10);
  document.getElementById('strideOut').textContent = state.stride;
  visited.clear();
  state.row = snapIdx(state.row, state.stride, 4);
  state.col = snapIdx(state.col, state.stride, 6);
  update();
});

let sweepTimer = null;
const btnSweep = document.getElementById('btnSweep');
function sweepAdvance() {
  const s = state.stride, nr = Math.ceil(4 / s), nc = Math.ceil(6 / s);
  let oi = (state.row - 1) / s + 1, oj = (state.col - 1) / s + 1;
  visited.add(oi + '_' + oj);
  oj++;
  if (oj > nc) { oj = 1; oi++; if (oi > nr) { oi = 1; visited.clear(); } }
  state.row = (oi - 1) * s + 1;
  state.col = (oj - 1) * s + 1;
  update();
}
function stopSweep() {
  if (sweepTimer) { clearInterval(sweepTimer); sweepTimer = null; btnSweep.innerHTML = '&#9654; Sweep kernel over input'; btnSweep.classList.remove('active'); }
}
btnSweep.addEventListener('click', () => {
  if (sweepTimer) { stopSweep(); return; }
  visited.clear();
  sweepTimer = setInterval(sweepAdvance, 620);
  btnSweep.innerHTML = '&#10073;&#10073; Pause sweep';
  btnSweep.classList.add('active');
});

/* ---------------- guided demo ---------------- */
const STEPS = [
  { title: 'a) Interior position → h₂₃', panel: 'a', stride: 1,
    text: 'The shaded 3×3 patch (rows 1–3, columns 2–4) multiplies element-wise with Ω (⊗) and the nine products are summed (⊕) into h₂₃.' },
  { title: 'b) Slide down-right → h₃₅', panel: 'b', stride: 1,
    text: 'The same kernel moves to rows 2–4, columns 4–6 and the filled output cell moves to h₃₅. The nine weights never change — that is weight sharing.' },
  { title: 'c) Left edge needs padding', panel: 'c', stride: 1,
    text: 'At column 1 the kernel hangs off the array, so a column of explicit 0 entries is supplied on the left; those zeros contribute nothing to h₃₁.' },
  { title: 'd) Top-right corner', panel: 'd', stride: 1,
    text: 'At the corner both a row above and a column to the right are zero-padded, yet h₁₆ is still a full 3×3 dot product.' },
  { title: 'Stride 2', panel: 'a', stride: 2,
    text: 'Raise the stride: the window jumps two cells at a time, most input positions are skipped, and the hidden layer shrinks to ⌈4/2⌉ × ⌈6/2⌉ = 2 × 3.' }
];
let stepIdx = 0;
const narrEl = document.getElementById('narr');
function goToStep(n) {
  stepIdx = (n + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  stopSweep(); visited.clear();
  state.stride = st.stride;
  strideSlider.value = String(st.stride);
  document.getElementById('strideOut').textContent = st.stride;
  const p = PANELS[st.panel];
  state.row = snapIdx(p.row, st.stride, 4);
  state.col = snapIdx(p.col, st.stride, 6);
  update();
  narrEl.innerHTML = `<b>${stepIdx + 1}/${STEPS.length} · ${st.title}</b><br>${st.text}`;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);
